 ct.innerHTML = '<div class="kpis">' + kpi('money', money(sum(fees.filter(f => !f.paid))), 'Total due (' + fees.filter(f => !f.paid).length + ')', 'r') + kpi('check', money(sum(fees.filter(f => f.paid))), 'Collected (all time)') + kpi('calendar', money(sum(fees.filter(f => f.paid && (f.paidOn || '').startsWith(today().slice(0, 7))))), 'Collected this month', 'b') + '</div><div class="pn"><h3>' + ic('card') + ' Fees' + (canW ? '<button class="btn sm" id="add">' + ic('plus') + ' Add fee</button><button class="btn ghost sm" id="gen">Generate for a class</button>' : '') + '<button class="btn ghost sm" id="xp"' + (canW ? '' : ' style="margin-left:auto"') + '>' + ic('download') + ' CSV</button></h3><div class="tbar"><div class="f"><label>Status</label><select id="fs">' + opts([['', 'All'], ['due', 'Due'], ['paid', 'Paid']]) + '</select></div><div class="f"><label>Class</label><select id="fc">' + clsO('', 'All classes') + '</select></div><div class="f"><label>Search</label><input id="fq" placeholder="Student or fee…"></div></div><div id="ft"></div></div>'; draw();
