/* ---------- inbox, leaves, messaging ---------- */
V.messages = async ct => {
 const canIn = ME.perms.r.includes('message'), canMsg = W('msg'); const [inbox, sent, studs] = await Promise.all([canIn ? list('message') : [], ME.perms.r.includes('msg') ? list('msg') : [], list('student')]);
 ct.innerHTML = (canMsg ? '<div class="pn"><h3>' + ic('msg') + ' Send a message to parents / students</h3><form id="mf2"><div class="row"><div class="f"><label>To</label><select id="mt2"><option value="|">Everyone</option>' + CL.map(c => '<option value="' + c + '|">' + cn(c) + ' (whole class)</option>').join('') + '<optgroup label="One student">' + byName(studs).sort((a, b) => CL.indexOf(a.cls) - CL.indexOf(b.cls)).map(s => '<option value="' + s.cls + '|' + s.id + '">' + cn(s.cls) + ' · ' + esc(s.name) + '</option>').join('') + '</optgroup></select></div><div class="f"><label>From</label><input id="mfr" value="' + esc(ME.name) + '"></div></div><div class="f"><label>Message</label><textarea id="mtx" required maxlength="500"></textarea></div><button class="btn">' + ic('arrow') + ' Send</button></form></div>' : '')
  + (canIn ? '<div class="pn"><h3>' + ic('mail') + ' Website contact messages <small style="color:var(--mut);font-weight:500">(' + inbox.length + ')</small></h3>' + (inbox.length ? inbox.sort((a, b) => b.date.localeCompare(a.date)).map(m => '<div class="msgi" style="' + (m.read ? 'opacity:.7' : '') + '"><b>' + esc(m.name) + '</b> · ' + esc(m.phone || '') + ' ' + esc(m.email || '') + ' <small>' + esc(m.date) + '</small>' + (m.read ? '' : ' <span class="badge b-wait">new</span>') + '<br>' + esc(m.text) + '<div style="margin-top:8px">' + (m.read ? '' : '<button class="btn ghost sm" data-a="r" data-id="' + m.id + '">Mark read</button> ') + '<button class="btn ghost sm" data-a="d" data-id="' + m.id + '">' + ic('trash') + '</button></div></div>').join('') : '<div class="empty">No messages yet</div>') + '</div>' : '')
  + '<div class="pn"><h3>' + ic('list') + ' Messages sent to families</h3>' + (sent.length ? tbl(['Date', 'To', 'From', 'Message'], sent.sort((a, b) => b.date.localeCompare(a.date)).slice(0, 30).map(m => '<tr><td>' + fd(m.date) + '</td><td>' + (m.sid ? (studs.find(s => s.id === m.sid) || {}).name || 'Student' : (m.cls ? cn(m.cls) : 'Everyone')) + '</td><td>' + esc(m.from) + '</td><td>' + esc(m.text) + '</td></tr>')) : '<div class="empty">Nothing sent yet</div>') + '</div>';
 if (canMsg) $('#mf2', ct).onsubmit = async e => { e.preventDefault(); const [cls, sid] = $('#mt2').value.split('|'); const r = await api('save', { body: { k: 'msg', d: { cls, sid, from: $('#mfr').value, text: $('#mtx').value, date: today() } } }); toast(r.demo ? 'Demo mode — not sent' : 'Message sent'); if (!r.demo) V.messages(ct); };
 ct.onclick = async e => { const b = e.target.closest('[data-a]'); if (!b) return; const m = inbox.find(x => x.id === b.dataset.id); if (b.dataset.a === 'r') { await save('message', m.id, Object.assign({}, m, { read: true })); } else if (confirm('Delete?')) await del(m.id); V.messages(ct); };
};
