  + sec(ic('book') + ' Academics', a('sub1', 'Subjects Class 1–5 (comma separated)', (s.subjects['1-5'] || []).join(', '), 2) + a('sub2', 'Subjects Class 6–10 (comma separated)', (s.subjects['6-10'] || []).join(', '), 2) + a('per', 'Class periods (one time slot per line)', (s.periods || []).join('\n'), 6) + a('fee', 'Fee structure — Class | Admission | Session | Monthly tuition | Exam fee', L(s.fees, f => [f.cls, f.admission, f.session, f.tuition, f.exam].join(' | ')), 12) + a('cal', 'Academic calendar — date | title | type (holiday / exam / event)', L(s.calendar, c => [c.date, c.title, c.type].join(' | ')), 9) + a('exr', 'Exam routine — date | subject | time', L(s.examRoutine, c => [c.date, c.subject, c.time].join(' | ')), 7))
