  n.fees = P(g('fee')).map(r => ({ cls: r[0], admission: +r[1] || 0, session: +r[2] || 0, tuition: +r[3] || 0, exam: +r[4] || 0 })); n.calendar = P(g('cal')).map(r => ({ date: r[0], title: r[1] || '', type: r[2] || 'event' })); n.examRoutine = P(g('exr')).map(r => ({ date: r[0], subject: r[1] || '', time: r[2] || '' }));
  n.facilities = P(g('fac')).map(r => ({ ico: r[0], title: r[1] || '', text: r[2] || '' })); n.achievers = P(g('ach')).map(r => ({ name: r[0], result: r[1] || '', exam: r[2] || '' })); n.reviews = P(g('rev')).map(r => ({ name: r[0], role: r[1] || '', text: r[2] || '' })); n.committee = P(g('com')).map(r => ({ name: r[0], role: r[1] || '' }));
